  if (!c.cadre) return base + 'fill/w_' + VIGNETTE + ',h_' + VIGNETTE + ',' + (c.fp ? 'fp_' + c.fp : 'al_c') + ',q_80,enc_auto/x.jpg';
  const [fx, fy, s] = c.cadre, cote = Math.round(s * Math.min(c.l, c.h));
