const dateCarte = (iso) => new Intl.DateTimeFormat(LANGUE_DATES, { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Europe/Paris' }).format(new Date(iso));
function carteRn(p, i) {
  const une = i === 0, video = p.k === 'video', st = CATS[p.k] || CATS.actualites;
  const ar = p.l && p.h ? p.l / p.h : 16 / 9;
  const tall = ar < 0.62 * (16 / 9);  
  const L = une ? 1040 : 640, H = Math.round(L / (une ? Math.max(1.5, Math.min(2.2, ar)) : 16 / 9));
  const img = tall
    ? '<img class="rn__thumb-bg" src="' + wix(p.c, 320, 180, 40) + '" alt="" aria-hidden="true" loading="lazy" decoding="async"><img class="rn__thumb-full" src="' + wixFit(p.c, L, H, 80) + '" alt="" loading="lazy" decoding="async">'
    : '<img src="' + wix(p.c, L, H, 78) + '" alt="" loading="lazy" decoding="async">';
  const marque = video ? '<span class="rn__playdisc" aria-hidden="true">' + RNIC.play + '</span>' : p.k === 'image' ? '<span class="rn__fmtic" aria-hidden="true">' + RNIC.cam + '</span>' : '';
  const badge = une ? '<span class="rn__unebadge">' + RNIC.anchor + 'À la une</span>' : '';
  const styleCat = video ? 'color:#B9E8E9;background:rgba(255,255,255,.12)' : 'color:' + st.c + ';background:' + st.bg;
  return '<article class="rn__card' + (video ? ' rn__card--video' : '') + (une ? ' rn__une' : '') + '">' +
    '<div class="rn__thumb' + (tall ? ' rn__thumb--tall' : '') + '"' + (une ? ' style="--ar:' + Math.max(1.5, Math.min(2.2, ar)).toFixed(3) + '"' : '') + '>' + img + marque + badge + '</div>' +
    '<div class="rn__body"><div class="rn__meta"><span class="rn__catbadge" style="' + styleCat + '">' + RNIC[st.ic] + st.lib + '</span>' +
    '<time datetime="' + p.d + '">' + dateCarte(p.d) + '</time>' + (p.m ? '<span class="rn__clock">' + RNIC.clock + p.m + ' min</span>' : '') + '</div>' +
    '<h3 class="rn__cardtitle"><a class="lien-carte" href="' + esc(p.u) + '">' + esc(p.t) + '</a></h3>' +
    (p.e ? '<p class="rn__excerpt">' + esc(p.e) + '</p>' : '') + '</div></article>';
}
